# verse data for Part 1
AV_Z='<svg class="av" viewBox="0 0 64 64" aria-hidden="true"><use href="#kiran"/></svg>'
AV_B='<svg class="av" viewBox="0 0 64 64" aria-hidden="true"><use href="#guru"/></svg>'
def talk(z,b):
    return f'<div class="talk"><div class="say z">{AV_Z}<p class="bubble"><span class="who">ZAPPY:</span> {z}</p></div><div class="say b">{AV_B}<p class="bubble"><span class="who">PROF. BOLT:</span> {b}</p></div></div>'
def svg(label,body,bg='#eef3fa'):
    return f'<svg width="220" height="160" viewBox="0 0 220 160" role="img" aria-label="{label}"><rect width="220" height="160" fill="{bg}"/>{body}</svg>'
T='font-family="Bangers"'
bird=lambda x,y,s=1: f'<path d="M{x-8*s} {y} q{4*s} {-6*s} {8*s} 0 q{4*s} {-6*s} {8*s} 0" fill="none" stroke="#111" stroke-width="2.5"/>'
LINGA='<g stroke="#111" stroke-width="2.5"><path d="M-30 0 h60 l-6 10 h-48z" fill="#7a7f8a"/><path d="M-14 0 v-26 a14 14 0 0 1 28 0 v26z" fill="#2b2f36"/><path d="M-8 -20 h16 M-8 -15 h16" stroke="#fff" stroke-width="2"/></g>'
V=[
dict(theme='EVEN BRAHMĀ\'S WORDS FALL SHORT',
 svg=svg('Birds flying at different heights into an endless sky that fades upward',
  '<rect width="220" height="160" fill="url(#sky)"/><defs><linearGradient id="sky" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#dcecff"/><stop offset="1" stop-color="#0b2a4a"/></linearGradient></defs>'
  +bird(40,130)+bird(80,104)+bird(120,80)+bird(160,56)+bird(190,34,.8)+f'<text x="110" y="18" text-anchor="middle" {T} font-size="12" fill="#ffd60a">NO END ABOVE</text><text x="40" y="152" text-anchor="middle" {T} font-size="10" fill="#111">ME</text><text x="190" y="52" text-anchor="middle" {T} font-size="10" fill="#fff">BRAHMĀ</text>'),
 mean='If praise by one who does not know the far shore of Your greatness is unfit, then even the words of Brahmā and the gods fall short of You. And if no one is to be blamed who praises You as far as their own understanding reaches, then this attempt of mine at a hymn, O Hara, is beyond reproach too.',
 plain='No one, not even Brahmā, can praise Śiva fully. So everyone praises Him as far as their mind can reach, and so may I.',
 words=[('mahimnaḥ pāram','the <b>far shore of Your greatness</b>'),('paramaviduṣaḥ','of one who does <b>not fully know</b> it'),('asadṛśī stutiḥ','an <b>unfit</b> praise'),('avasannāḥ giraḥ','words that <b>sink, fall short</b>'),('svamati-pariṇāmāvadhi','<b>up to the limit of one\'s own mind</b>'),('nirapavādaḥ parikaraḥ','an effort <b>beyond reproach</b>')],
 deep='<p><b>The poet\'s apology.</b> Puṣpadanta opens the way many great hymns do: by admitting the task is impossible. If only someone who knew Śiva completely could praise Him, then no one could, not even Brahmā, the creator, whose speech is the Veda itself.</p><p><b>The birds in the sky.</b> Commentators give an image for this verse: birds fly into the sky, each as high as its wings can carry it. None reaches the end of the sky, yet none is wrong to fly. So with praise: each devotee rises as far as they can.</p><p><b>Hara.</b> The first name the poet uses is <i>Hara</i>, "the one who takes away", sin and sorrow. The thief who has lost his powers begins by calling on the One who removes.</p>',
 cards=('💡 Mahimna','<i>Mahiman</i> means greatness. <i>Mahimnaḥ</i>, "of the greatness", is the hymn\'s first word and gives it its name.','💡 The metre','<i>Śikhariṇī</i>: seventeen syllables a line, with a pause after the sixth. Its name means "the peaked one".'),
 inner='No one\'s prayer is too small. Offer what you understand; the limit is yours, the greatness is His.',
 talk=('If even Brahmā can\'t praise Him properly, why try?','Because nobody is asked to reach the end of the sky, only to fly. The hymn begins by setting us all free to try.'),
 key='Praise as far as your mind can reach: <b>no one is blamed for falling short</b>.'),
dict(theme='BEYOND SPEECH AND MIND',
 svg=svg('A glowing light in the centre with arrows labelled not this pointing away, and a small figure of Shiva below',
  f'<circle cx="110" cy="62" r="34" fill="#ffd60a" opacity=".85"/><circle cx="110" cy="62" r="48" fill="#ffd60a" opacity=".25"/>'
  +''.join(f'<path d="M{110+40*c} {62+40*s} L{110+70*c} {62+70*s}" stroke="#c0392b" stroke-width="3" marker-end="url(#ar)"/>' for c,s in [(1,0),(-1,0),(0.7,-0.7),(-0.7,-0.7)])
  +f'<defs><marker id="ar" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6z" fill="#c0392b"/></marker></defs><text x="190" y="58" {T} font-size="10" fill="#c0392b">NOT THIS</text><text x="6" y="58" {T} font-size="10" fill="#c0392b">NOT THIS</text><g transform="translate(110 146)">{LINGA}</g>'),
 mean='Your greatness lies beyond the path of speech and mind; even the Veda speaks of it in awe, only by saying what it is not. Who can praise it? Of how many qualities is it? Whose object can it be? Yet on Your nearer form, whose mind does not fall, whose speech does not fall?',
 plain='Śiva in Himself cannot be described; the Veda only says "not this, not this". But His visible form draws every mind and every tongue.',
 words=[('atītaḥ panthānam','<b>beyond the path</b>'),('vāṅ-manasayoḥ','<b>of speech and mind</b>'),('atad-vyāvṛttyā','by <b>excluding what it is not</b>'),('cakitam','<b>in awe</b>, startled'),('śrutiḥ','the <b>Veda</b>'),('pade arvācīne','<b>in the nearer form</b>, the form we can see')],
 deep='<p><b>Neti, neti.</b> <i>Atad-vyāvṛttyā</i>, "by setting aside what it is not", points to the Upaniṣadic method of <i>neti neti</i>, "not this, not this". The ultimate cannot be pointed at, only approached by removing every wrong idea.</p><p><b>The startled Veda.</b> <i>Cakitam</i>, startled or awed: the poet pictures the Veda itself hesitating before Śiva, like someone afraid to say the wrong word.</p><p><b>The nearer form.</b> The last line turns: but when Śiva takes a form, the moon-crowned, three-eyed Lord with the Gaṅgā in His hair, every mind falls in love and every tongue starts singing. That is what the rest of the hymn will do.</p>',
 cards=('💡 Two levels','<b>Nirguṇa</b>, beyond qualities, and <b>saguṇa</b>, with qualities: the hymn honours both.','💡 Kena Upaniṣad','"That from which speech turns back, with the mind": the same thought, in the Upaniṣads.'),
 inner='What can\'t be grasped can still be loved. The formless is why we are humble; the form is why we can sing.',
 talk=('If He can\'t be described, what is the rest of the hymn doing?','Describing the form He takes for us. The poet knows the difference, and says so before he begins.'),
 key='Beyond words in Himself, <b>irresistible in His form</b>.'),
dict(theme='WHY I SING ANYWAY',
 svg=svg('Golden drops of honey falling from a scroll into a small bowl, beside a lamp',
  f'<rect x="40" y="26" width="140" height="44" rx="8" fill="#fff3b0" stroke="#111" stroke-width="2.5"/><text x="110" y="54" text-anchor="middle" {T} font-size="14" fill="#c0392b">THE VEDA</text>'
  +''.join(f'<circle cx="{x}" cy="{y}" r="4" fill="#e0a800" stroke="#111" stroke-width="1"/>' for x,y in [(90,82),(110,92),(130,84),(110,108)])
  +'<path d="M80 126 h60 l-8 18 h-44z" fill="#c9a26b" stroke="#111" stroke-width="2.5"/><path d="M168 132 h22 l-3 6 h-16z" fill="#e0a800" stroke="#111" stroke-width="2"/><path d="M179 132 q-6 -12 0 -18 q6 6 0 18z" fill="#ff8c1a" stroke="#111" stroke-width="1.5"/>'),
 mean='You made the Vedas, speech swollen with honey, the supreme nectar: O Brahman, can even the words of Bṛhaspati, guru of the gods, amaze You? It is to purify this speech of mine by the merit of telling Your qualities, O destroyer of the cities, that my mind has resolved on this.',
 plain='Śiva wrote the Vedas; no poem can impress Him. The poet sings not to impress, but to make his own speech pure.',
 words=[('madhu-sphītāḥ vācaḥ','<b>honey-filled words</b>: the Veda'),('nirmitavataḥ','of <b>the One who made</b>'),('suraguru','<b>guru of the gods</b>: Bṛhaspati'),('vismaya-padam','a <b>cause of wonder</b>'),('punāmi','<b>I purify</b>'),('puramathana','<b>destroyer of the (three) cities</b>')],
 deep='<p><b>Not to impress.</b> If Bṛhaspati, the most eloquent of the gods, cannot amaze Śiva, what can a fallen gandharva add? Nothing. So the poet changes the purpose of praise: it is not for Śiva, it is for the singer.</p><p><b>Purifying speech.</b> <i>Punāmi</i>, "I purify". Telling the qualities of the Lord is like washing the tongue. In the story, Puṣpadanta has fallen; this is the first step back.</p><p><b>Puramathana.</b> The hymn often calls Śiva the destroyer of <b>Tripura</b>, the three flying cities of the demons. Part 2 tells that story in full.</p>',
 cards=('💡 Bṛhaspati','Guru of the gods, master of speech and wisdom; lord of the planet Jupiter.','💡 Brahman','Here Śiva is addressed as <i>Brahman</i>: the ultimate reality itself.'),
 inner='We don\'t pray to change God\'s mind. We pray to change our own.',
 talk=('So prayer is really for us?','That\'s what Puṣpadanta says. Śiva needs nothing; we are the ones who are cleaned by remembering Him.'),
 key='The hymn doesn\'t add to Śiva: <b>it purifies the one who sings</b>.'),
dict(theme='ONE LORD, THREE FORMS',
 svg=svg('One light above dividing into three figures: red Brahma creating, blue Vishnu protecting, white Rudra dissolving',
  '<circle cx="110" cy="30" r="18" fill="#ffd60a" stroke="#111" stroke-width="2.5"/><path d="M110 48 L46 96 M110 48 L110 96 M110 48 L174 96" stroke="#ff8c1a" stroke-width="3"/>'
  +f'<circle cx="46" cy="112" r="20" fill="#e63946" stroke="#111" stroke-width="2.5"/><circle cx="110" cy="112" r="20" fill="#1d6fb8" stroke="#111" stroke-width="2.5"/><circle cx="174" cy="112" r="20" fill="#f5f5f5" stroke="#111" stroke-width="2.5"/><text x="46" y="150" text-anchor="middle" {T} font-size="10">CREATE · RAJAS</text><text x="110" y="150" text-anchor="middle" {T} font-size="10">PROTECT · SATTVA</text><text x="174" y="150" text-anchor="middle" {T} font-size="10">DISSOLVE · TAMAS</text>'),
 mean='Your lordship, which brings about the rise, the protection and the dissolution of the world, and which the three Vedas describe, divided among three bodies distinguished by the three qualities: O giver of boons, some dull-witted people raise a loud protest here to destroy it, a protest pleasing to the unfortunate, but not pleasing in truth.',
 plain='Śiva\'s one power appears as three: creator, protector, destroyer. Some people argue against it; the poet calls their noise unconvincing.',
 words=[('udaya-rakṣā-pralaya','<b>rise, protection, dissolution</b>'),('trayī','the <b>three Vedas</b>'),('tisṛṣu tanuṣu','<b>in three bodies</b>'),('guṇa-bhinnāsu','<b>divided by the three guṇas</b>'),('varada','<b>giver of boons</b>'),('jaḍa-dhiyaḥ','<b>dull-witted</b> people')],
 deep='<p><b>The Trimūrti.</b> One power, three functions. Brahmā creates through <i>rajas</i> (activity), Viṣṇu protects through <i>sattva</i> (clarity), Rudra dissolves through <i>tamas</i> (rest). The hymn says all three are Śiva\'s lordship working through three forms.</p><p><b>Answering the doubters.</b> Verses 4 to 6 answer people who deny a creator. Puṣpadanta, a singer, briefly becomes a debater. Their argument, he says, sounds attractive to some but cannot stand.</p><p><b>Not sectarian.</b> Many readers note how the hymn honours Brahmā and Viṣṇu as Śiva\'s own forms. Verse 7 will go further.</p>',
 cards=('💡 Three guṇas','<b>Sattva</b>, <b>rajas</b>, <b>tamas</b>: clarity, activity, inertia, the three strands of nature in Sāṅkhya.','💡 Trimūrti','Brahmā, Viṣṇu and Śiva as three faces of one divine power.'),
 inner='One light can wear different faces for different jobs. Don\'t mistake the faces for different lights.',
 talk=('So Brahmā and Viṣṇu are Śiva?','In this hymn, yes: one lordship in three bodies. A Vaiṣṇava hymn would say the same of Viṣṇu. The light is one.'),
 key='Creation, protection, dissolution: <b>one power in three forms</b>.'),
dict(theme='THE QUESTIONS OF THE DOUBTER',
 svg=svg('A potter at his wheel surrounded by question marks: what desire, what body, what tools, what clay',
  '<ellipse cx="110" cy="120" rx="44" ry="10" fill="#9a7a5a" stroke="#111" stroke-width="2.5"/><path d="M92 120 q-4 -30 18 -36 q22 6 18 36z" fill="#c9a26b" stroke="#111" stroke-width="2.5"/>'
  +''.join(f'<text x="{x}" y="{y}" text-anchor="middle" {T} font-size="{s}" fill="#c0392b">?</text>' for x,y,s in [(40,40,28),(180,44,28),(60,86,22),(164,92,22),(110,40,30)])
  +f'<text x="40" y="60" text-anchor="middle" {T} font-size="9">DESIRE?</text><text x="180" y="64" text-anchor="middle" {T} font-size="9">BODY?</text><text x="60" y="104" text-anchor="middle" {T} font-size="9">TOOLS?</text><text x="164" y="110" text-anchor="middle" {T} font-size="9">CLAY?</text><text x="110" y="150" text-anchor="middle" {T} font-size="10">WHO MAKES THE WORLD?</text>'),
 mean='"With what desire, what body, what means, what support, and from what material does the Creator make the three worlds?" Such bad reasoning about You, whose lordship is beyond reasoning, finds no ground to stand on; yet it makes some people talkative, to confuse the world.',
 plain='Doubters ask: if God made the world, with what wish, what body, what tools, what material? The poet says: You are beyond such reasoning; the questions confuse more than they explain.',
 words=[('kim-īhaḥ','<b>with what desire?</b>'),('kim-kāyaḥ','<b>with what body?</b>'),('kim-upāyaḥ','<b>by what means?</b>'),('kim-upādānaḥ','<b>from what material?</b>'),('atarkya-aiśvarye','<b>whose lordship is beyond logic</b>'),('kutarkaḥ','<b>bad reasoning</b>')],
 deep='<p><b>The potter argument.</b> A pot needs a potter, wanting a pot, with hands, a wheel and clay. The doubter asks: if the world needs a maker, show me His desire, His hands, His tools, His clay.</p><p><b>The poet\'s answer.</b> Those questions treat God like a potter, a being inside the world. But the One who makes the world is not inside it; He is the ground of it. Asking "with what clay?" of the source of all clay misses the point. In Vedānta, the Lord is both the maker and the material of the world.</p><p><b>Mukharayati.</b> "Makes them talkative": a sharp, slightly comic word. Bad arguments, says the poet, produce a lot of talk.</p>',
 cards=('💡 Upādāna','The <b>material cause</b>: clay is the material cause of a pot; the Lord is called both maker and material of the world.','💡 Debate','Ancient Indian schools argued fiercely about a creator; the Mīmāṃsakas and others questioned one.'),
 inner='Some questions are like asking where the ocean keeps its waves. The answer is: in itself.',
 talk=('But those are good questions!','Good questions about a potter. Puṣpadanta says the Lord isn\'t a bigger potter; He\'s the reason there is clay at all.'),
 key='The Maker of the world <b>is not a bigger potter</b>.'),
dict(theme='CAN A WORLD MAKE ITSELF?',
 svg=svg('A house built of bricks with a question: can parts put themselves together without a builder',
  '<g stroke="#111" stroke-width="2"><path d="M60 120 v-44 l50 -34 l50 34 v44z" fill="#e8c27a"/>'+''.join(f'<rect x="{60+20*i}" y="{100+0}" width="20" height="10" fill="#c0703a"/>' for i in range(5))+''.join(f'<rect x="{70+20*i}" y="90" width="20" height="10" fill="#c0703a"/>' for i in range(4))+'</g>'
  +f'<rect x="96" y="104" width="0" height="0"/><text x="110" y="24" text-anchor="middle" {T} font-size="12" fill="#1d4f9a">MADE OF PARTS…</text><text x="110" y="148" text-anchor="middle" {T} font-size="12" fill="#c0392b">…BUT NO BUILDER?</text><text x="190" y="80" text-anchor="middle" {T} font-size="28" fill="#c0392b">?</text>'),
 mean='Are the worlds unborn, though they are made of parts? Does creation happen without regard to a ruler of the worlds? Or if no Lord made it, what means could there be for bringing the worlds into being? Since that is so, it is the dull who doubt You, O best of the immortals.',
 plain='Things made of parts are made. If the world has parts, it had a beginning; and something made needs a maker. Only the dull doubt the Lord.',
 words=[('ajanmānaḥ','<b>unborn</b>'),('avayavavantaḥ','<b>made of parts</b>'),('adhiṣṭhātā','the <b>ruler, overseer</b>'),('anīśaḥ','<b>without a Lord</b>'),('mandāḥ','the <b>dull</b>'),('amaravara','<b>best of the immortals</b>')],
 deep='<p><b>The classical argument.</b> This is the Nyāya argument for God, in poetry: whatever has parts is produced; whatever is produced has an intelligent cause; the world has parts; so the world has an intelligent cause.</p><p><b>Turning the tables.</b> In verse 5 the doubter asked hard questions. Here the poet asks his own: if no one made the world, how did it come about? He says the doubter has no better answer.</p><p><b>A poet\'s debate.</b> Arguments like this were the daily bread of Indian philosophy. That a hymn of devotion stops to answer them shows how seriously its audience took both reason and faith.</p>',
 cards=('💡 Nyāya','The Indian school of logic; its thinkers, such as Udayana, built careful proofs for a creator.','💡 Parts and wholes','"What has parts is produced" was the key premise: a pot, a cloth, a house, a world.'),
 inner='Faith is not afraid of reason. Puṣpadanta argues first and sings after.',
 talk=('Does this argument prove God?','People still debate it, in India and everywhere. The hymn\'s point is gentler: doubt is not more reasonable than faith.'),
 key='A world made of parts <b>points to a Maker</b>.'),
dict(theme='MANY RIVERS, ONE OCEAN',
 svg=svg('Five rivers, some straight and some winding, all flowing into one ocean',
  '<rect x="0" y="118" width="220" height="42" fill="#1d6fb8"/><text x="110" y="146" text-anchor="middle" font-family="Bangers" font-size="13" fill="#fff">ŚIVA · THE OCEAN</text>'
  +''.join(f'<path d="{d}" fill="none" stroke="#4aa3df" stroke-width="5"/>' for d in ['M20 10 C 40 50, 0 80, 40 118','M70 10 L 80 118','M120 10 C 90 40, 150 70, 110 118','M170 10 C 200 60, 140 80, 160 118','M210 20 L 196 118'])
  +f'<text x="22" y="8" {T} font-size="8">VEDA</text><text x="62" y="8" {T} font-size="8">SĀṄKHYA</text><text x="110" y="8" {T} font-size="8">YOGA</text><text x="150" y="8" {T} font-size="8">PĀŚUPATA</text><text x="186" y="18" {T} font-size="8">VAIṢṆAVA</text>'),
 mean='The three Vedas, Sāṅkhya, Yoga, the doctrine of Paśupati, the Vaiṣṇava path: these schools are distinct, and each says "this is supreme, that is beneficial". Because of the variety of tastes, people follow paths straight or winding, many paths; yet for all of them You alone are the goal, as the ocean is for all waters.',
 plain='Different people follow different paths, straight or crooked, by temperament. All of them lead to the same Lord, as all rivers lead to the sea.',
 words=[('trayī','the <b>three Vedas</b>'),('sāṅkhyam · yogaḥ','the <b>Sāṅkhya</b> and <b>Yoga</b> schools'),('paśupati-matam','the <b>Pāśupata</b> (Śaiva) doctrine'),('rucīnāṃ vaicitryāt','<b>because of the variety of tastes</b>'),('ṛju-kuṭila','<b>straight or winding</b>'),('payasām arṇava iva','<b>like the ocean for waters</b>')],
 deep='<p><b>The most famous verse.</b> This is the line of the Mahimna that the world knows best. On 11 September 1893, at the Parliament of the World\'s Religions in Chicago, Swami Vivekananda quoted it in his opening address: as streams from different sources all mingle their water in the sea, so the different paths people take, straight or crooked, all lead to God.</p><p><b>Not "all paths are the same".</b> The verse says paths really differ, and that each school thinks itself best. It does not erase the differences. It says the <b>goal</b> is one, and the variety comes from human temperament.</p><p><b>Śaiva and Vaiṣṇava together.</b> A hymn to Śiva names the Vaiṣṇava path as one of the rivers to the same sea.</p>',
 cards=('💡 Chicago, 1893','Vivekananda\'s welcome speech quoted this verse in English; it is still read today.','💡 Ruci','"Taste" or "inclination": people choose paths that suit their nature.'),
 inner='Your path may wind and your neighbour\'s run straight. Don\'t mock the other river; you are heading to the same sea.',
 talk=('So every religion is right?','The verse is careful: the paths are different, some straight, some winding. But every sincere seeker ends at the same ocean.'),
 key='Straight or winding, <b>every river reaches the sea</b>.'),
dict(theme='A BULL, AN AXE, A SKULL',
 svg=svg('Shiva\'s possessions: a bull, a club with a skull, an axe, an elephant hide, ash, snakes and a skull bowl, beside gods holding treasure',
  '<g stroke="#111" stroke-width="2.2">'
  '<path d="M20 100 q0 -18 22 -18 q22 0 24 12 l8 2 l-8 6 v12 h-46z" fill="#fff"/><path d="M60 84 l6 -10 M48 84 l-4 -10" />'
  '<path d="M96 40 v80" stroke-width="4"/><circle cx="96" cy="36" r="8" fill="#fff"/>'
  '<path d="M130 40 v80" stroke-width="4"/><path d="M130 44 q16 0 16 16 q-16 0 -16 -4z" fill="#bbb"/>'
  '<path d="M160 120 q10 -40 30 -20 q10 10 -6 20" fill="none" stroke="#2a9d6f" stroke-width="4"/>'
  '<path d="M172 60 q16 -2 18 12 q-8 10 -18 0z" fill="#fff"/></g>'
  f'<text x="110" y="148" text-anchor="middle" {T} font-size="11">ALL HE OWNS · AND ALL HE GIVES</text><text x="44" y="122" text-anchor="middle" {T} font-size="9">NANDI</text><text x="96" y="130" text-anchor="middle" {T} font-size="9">KHAṬVĀṄGA</text><text x="130" y="130" text-anchor="middle" {T} font-size="9">AXE</text><text x="182" y="132" text-anchor="middle" {T} font-size="9">SNAKE</text>'),
 mean='An old bull, a skull-topped staff, an axe, a hide, ash, snakes and a skull: that is all Your household gear, O giver of boons. Yet the gods hold their great riches, set before them by a mere movement of Your brow. Truly, the mirage of sense objects does not bewilder one who delights in his own Self.',
 plain='Śiva owns almost nothing: a bull, a skull, ash and snakes. Yet He gives the gods all their wealth with a glance. One who is content in the Self isn\'t fooled by the mirage of possessions.',
 words=[('mahokṣaḥ','the <b>great bull</b>: Nandi'),('khaṭvāṅgam','a <b>staff topped with a skull</b>'),('paraśuḥ · ajinam','an <b>axe</b> · a <b>hide</b>'),('bhasma · phaṇinaḥ','<b>ash</b> · <b>snakes</b>'),('bhrū-praṇihitām','<b>placed by a movement of the brow</b>'),('viṣaya-mṛgatṛṣṇā','the <b>mirage of sense objects</b>')],
 deep='<p><b>The poorest rich man.</b> The verse lists Śiva\'s whole "household": Nandi, the khaṭvāṅga, the axe, an elephant or tiger hide, ash from the cremation ground, snakes as ornaments, a skull for a begging bowl. Indra\'s heaven, Kubera\'s treasury and the gods\' palaces were all, says the poet, given by a flick of His eyebrow.</p><p><b>Svātmārāma.</b> The key word: one who "delights in his own Self". Such a person does not need things, so they cannot trap him. A mirage only fools a thirsty deer.</p><p><b>For us.</b> The verse is also advice: it is not owning that binds, but wanting.</p>',
 cards=('💡 Mṛgatṛṣṇā','"The deer\'s thirst": a mirage, water that isn\'t there, chased by a thirsty deer.','💡 The ascetic','Śiva is the model yogī: owning nothing, needing nothing, giving everything.'),
 inner='Owning little and giving much is a kind of wealth no treasury can hold.',
 talk=('He gives away palaces and keeps a skull?','Because He doesn\'t need palaces. Someone happy in himself isn\'t chasing the mirage the rest of us run after.'),
 key='Owner of nothing, <b>giver of everything</b>.'),
dict(theme='PERMANENT? IMPERMANENT? BOTH?',
 svg=svg('Three philosophers arguing with speech bubbles: all is permanent, all is impermanent, it is both',
  ''.join(f'<circle cx="{x}" cy="110" r="14" fill="#f2c79b" stroke="#111" stroke-width="2.5"/><path d="M{x-16} 150 q16 -30 32 0z" fill="{c}" stroke="#111" stroke-width="2.5"/>' for x,c in [(40,'#e63946'),(110,'#1d6fb8'),(180,'#2a9d6f')])
  +''.join(f'<rect x="{x-34}" y="{y}" width="68" height="34" rx="10" fill="#fff" stroke="#111" stroke-width="2"/><text x="{x}" y="{y+21}" text-anchor="middle" {T} font-size="10">{t}</text>' for x,y,t in [(40,24,'ALL LASTS!'),(110,46,'NOTHING LASTS!'),(180,24,'BOTH!')])),
 mean='Some say all this is permanent; another says it is all impermanent; another says the world is both, permanent and impermanent in different respects. Amazed, as it were, by all of them, O destroyer of the cities, I praise You without shame: surely, talkativeness is bold!',
 plain='Philosophers argue: the world is permanent, impermanent, or both. Bewildered by them all, the poet just praises Śiva, and laughs at his own boldness.',
 words=[('dhruvam','<b>permanent</b>, fixed'),('adhruvam','<b>impermanent</b>'),('dhrauvya-adhrauvye','<b>both permanence and impermanence</b>'),('vismitaḥ','<b>amazed</b>, bewildered'),('jihremi','<b>I am ashamed</b> (here: na jihremi, I am not)'),('dhṛṣṭā mukharatā','<b>bold talkativeness</b>')],
 deep='<p><b>The schools.</b> Commentators match the three views to Indian schools: some held the world, or its building blocks, to be eternal; the Buddhists taught that everything is momentary; others held a middle view, permanent in substance and changing in form.</p><p><b>The poet steps back.</b> After three verses of debate, Puṣpadanta laughs at himself. The philosophers can keep arguing; he is "amazed" by all of them, and he will simply sing.</p><p><b>Humour in a hymn.</b> "Talkativeness is bold" is a joke at his own expense: who is he, a disgraced gandharva, to praise the Lord? Yet here he is, talking.</p>',
 cards=('💡 Kṣaṇikavāda','The Buddhist teaching that all things are momentary, arising and passing each instant.','💡 Pariṇāma','Sāṅkhya\'s view that the world truly changes form while its substance remains.'),
 inner='Arguments have their place. But at some point you stop debating the ocean and jump in.',
 talk=('He just gives up the argument?','He steps back from it. When the debate gets tiring, praise is still possible. And he laughs at himself, which is rare in a hymn.'),
 key='Let the schools argue: <b>I will just praise You</b>.'),
dict(theme='THE PILLAR OF FIRE',
 svg=svg('An endless column of fire with a swan flying upward and a boar digging downward, neither reaching the end',
  '<rect width="220" height="160" fill="#16264a"/><rect x="92" y="0" width="36" height="160" fill="#ffd60a"/><path d="M92 0 V160 M128 0 V160" stroke="#ff8c1a" stroke-width="4"/>'
  '<g transform="translate(160 32)"><path d="M-14 0 q14 -10 28 0 q-14 8 -28 0z" fill="#fff" stroke="#111" stroke-width="2"/><path d="M10 -2 q8 -14 2 -18 l6 -2" fill="none" stroke="#111" stroke-width="2"/></g>'
  '<g transform="translate(56 132)"><path d="M-18 0 q0 -14 18 -14 q16 0 18 10 l6 2 l-6 4 v6 h-36z" fill="#7a5a3a" stroke="#111" stroke-width="2"/></g>'
  f'<text x="170" y="62" text-anchor="middle" {T} font-size="10" fill="#fff">BRAHMĀ ↑</text><text x="56" y="112" text-anchor="middle" {T} font-size="10" fill="#fff">VIṢṆU ↓</text>'),
 mean='When Viriñci (Brahmā) went upward and Hari (Viṣṇu) downward, striving to measure Your glory as You took the form of a pillar of fire, they failed. Then, O Lord of the mountain, when the two praised You, heavy with devotion and faith, You stood before them of Your own accord. Does following You not bear fruit?',
 plain='Brahmā flew up and Viṣṇu dug down to find the end of Śiva\'s pillar of fire, and failed. When they gave up and praised Him with devotion, He appeared to them. Devotion succeeds where effort fails.',
 words=[('viriñciḥ · hariḥ','<b>Brahmā</b> · <b>Viṣṇu</b>'),('upari · adhaḥ','<b>above</b> · <b>below</b>'),('paricchetum','<b>to measure, to find the limit</b>'),('anala-skandha-vapuṣaḥ','of You <b>in the form of a column of fire</b>'),('bhakti-śraddhā','<b>devotion and faith</b>'),('giriśa','<b>Lord of the mountain</b>')],
 deep='<p><b>Liṅgodbhava.</b> The story of the jyotirliṅgas: Brahmā and Viṣṇu quarrel, an endless pillar of fire appears, Brahmā becomes a swan and flies up, Viṣṇu becomes a boar and digs down. Neither finds an end. (Our Liṅgāṣṭakam article and the 12 Jyotirliṅgas series tell it in full.)</p><p><b>The twist here.</b> The Mahimna adds what many tellings rush past: Śiva appears not when they succeed, but when they stop measuring and start praising. <i>Svayaṃ tasthe</i>: "You stood before them, of Yourself."</p><p><b>The question.</b> The verse ends with a question for us: <i>kim anuvṛttir na phalati</i>, does devotion ever go unrewarded?</p>',
 cards=('💡 Liṅgodbhava','The image of Śiva emerging from the pillar of fire, on the west wall of many South Indian Śiva temples.','💡 Giriśa','"Lord of the mountain": Śiva of Kailāsa.'),
 inner='You can\'t measure God from outside. When the measuring stops and the bowing begins, He comes to you.',
 talk=('So even Brahmā and Viṣṇu had to stop and pray?','That\'s the point of the story. Effort found nothing; devotion found everything.'),
 key='Measuring failed; <b>devotion brought Him near</b>.'),
dict(theme='TEN HEADS AS LOTUSES',
 svg=svg('A row of ten lotuses offered at the base of a linga, standing for the ten heads of Ravana',
  f'<g transform="translate(110 100)">{LINGA}</g>'
  +''.join(f'<g transform="translate({22+19.5*i} 136)"><path d="M0 0 q-8 -12 0 -20 q8 8 0 20z M0 0 q-12 -6 -12 -14 q8 2 12 14z M0 0 q12 -6 12 -14 q-8 2 -12 14z" fill="#f08aa6" stroke="#111" stroke-width="1.2"/></g>' for i in range(10))
  +f'<text x="110" y="26" text-anchor="middle" {T} font-size="12" fill="#c0392b">TEN HEADS · TEN LOTUSES</text>'),
 mean='That the ten-headed Rāvaṇa won the three worlds without effort, free of all enemies, and still had arms itching for battle: O destroyer of Tripura, that was only the flowering of his firm devotion to You, he who made an offering of a row of his own heads, like lotuses, at Your lotus feet.',
 plain='Rāvaṇa conquered the three worlds easily. The poet says it was the reward of his devotion: he once offered his own heads to Śiva like lotus flowers.',
 words=[('ayatnāt','<b>without effort</b>'),('avaira-vyatikaram','<b>without any enemy</b> left to fight'),('daśāsyaḥ','the <b>ten-faced</b>: Rāvaṇa'),('raṇa-kaṇḍū','the <b>itch for battle</b>'),('śiraḥ-padma-śreṇī','<b>a row of heads like lotuses</b>'),('visphūrjitam','the <b>blossoming, the outcome</b>')],
 deep='<p><b>The offering.</b> Tradition tells that Rāvaṇa, doing penance for Śiva, cut off his heads one by one and offered them into the fire, or at the Lord\'s feet. Before the tenth, Śiva appeared and restored them all. The poet calls the heads "a row of lotuses".</p><p><b>Power from devotion.</b> Rāvaṇa\'s conquest of the three worlds, with arms still itching for more battles, was the fruit of that devotion, says the verse.</p><p><b>What comes next.</b> Verse 12 opens Part 2: the same Rāvaṇa, swollen with power, tries to lift Kailāsa itself. Devotion gave him strength; pride will press him down.</p>',
 cards=('💡 Daśāsya','"Ten-faced": one of Rāvaṇa\'s names, with Daśagrīva and Daśakaṇṭha.','💡 Rāvaṇa and Śiva','He is also the traditional singer of the Śiva Tāṇḍava Stotram; see our article.'),
 inner='Whatever you offer wholeheartedly comes back many times over. What you then do with it is your own test.',
 talk=('Rāvaṇa was a devotee?','One of Śiva\'s greatest, in tradition. His fall came later, from pride, which is exactly where verse 12 begins.'),
 key='Rāvaṇa\'s power <b>was the fruit of his devotion</b>.'),
]
